public class StatisticsService {


	public static Collection<Statistics> getStatistics(StatisticsRepository repository, Collection<String> organizations, String startDate, String endDate){

		Collection<Statistics> statistics = new ArrayList<>(organizations.size());

		List<Statistics> unaggregatedStatistics = new ArrayList<>();

		if (startDate == null && endDate == null) {
			for (String orgName : organizations) {

				List<Statistics> s = repository.findByOrganizationNameOrderByKeySnapshotDateDesc(orgName,
						new PageRequest(0, 1));

				unaggregatedStatistics.addAll(s);
			}

			if (unaggregatedStatistics.size() > 0) {
				Statistics aggregatedStatistics = aggregateStatistics(unaggregatedStatistics);

				statistics.add(aggregatedStatistics);
			}

		} else {
			// filter by start and end date
			statistics = getStatisticsByDate(repository, organizations, startDate, endDate);
		}

		return statistics;
	}


	private static Collection<Statistics> getStatisticsByDate(StatisticsRepository repository, Collection<String> orgs, String startDate, String endDate) {

		Date start = null;
		Date end;
		try {
			if (startDate != null) {
				start = StringParser.parseIso8601Date(startDate);
			}
		} catch (ParseException e) {
			throw new IllegalArgumentException(Constants.ERR_MSG_WRONG_DATE_FORMAT + " for stardDate");
		}

		try {
			end = endDate == null ? new Date() : StringParser.parseIso8601Date(endDate);
		} catch (ParseException e) {
			throw new IllegalArgumentException(Constants.ERR_MSG_WRONG_DATE_FORMAT + " for endDate");
		}

		List<List<Statistics>> statisticsLists = collectStatistics(repository, orgs, start, end);

		return aggregateHistoricalStatistics(statisticsLists);
	}


	private static List<List<Statistics>> collectStatistics(StatisticsRepository repository, Collection<String> organizations, Date start, Date end) {

		List<List<Statistics>> statisticsLists = new ArrayList<>();

		// get statistics for each organization
		for (String orgName : organizations) {

			if (start == null) {
				Optional<Date> earliestSnapshot = repository.getEarliestSnaphotDate(orgName);
				if (earliestSnapshot.isPresent()) {
					start = earliestSnapshot.get();
				} else {
					continue;
				}
			} else {
				Optional<Date> earlierSnapshot = repository.getLatestSnaphotDateBefore(orgName, start);

				if (earlierSnapshot.isPresent()) {
					start = earlierSnapshot.get();
				} 
			}

			if (start.after(end)) {
				continue;
				// throw new IllegalArgumentException("Start date is after end
				// date");
			}

			List<Statistics> s = repository.findStatisticsByOrganizationAndDate(orgName, start, end);
			statisticsLists.add(s);
		}

		return statisticsLists;
	}



	/**
	 * Aggregates a collection of {@link Statistics} objects by adding up their field values
	 * 
	 * @param statistics The {@link Collection} of {@link Statistics} objects to be merged
	 * @return A {@link Statistics} object whole field values are the sum of the given field values of the input Statistics objects.
	 * @throws IllegalArgumentException If an invariant has been violated
	 */
	public static Statistics aggregateStatistics(Collection<Statistics> statistics) throws IllegalArgumentException{

		if(statistics==null || statistics.size()==0){
			throw new IllegalArgumentException("Illegal number of statistics to aggregate");
		}

		String delimeter = ", ";

		if(statistics.size()==1) return statistics.iterator().next();

		Integer contributers = 0, externalContributors = 0, forks = 0, size = 0, stars = 0, members = 0, privateProjects = 0, languages = 0,
				publicProjects = 0, tags = 0, teams = 0;


		Date snapshotDate = null;

		Set<String> organizationList = new HashSet<>();

		//aggregate data
		for (Statistics s : statistics) {
			contributers = add(contributers, s.getAllContributorsCount());
			externalContributors = add(externalContributors, s.getExternalContributorsCount());
			forks = add(forks, s.getAllForksCount());
			size = add(size, s.getAllSizeCount());
			stars = add(stars, s.getAllStarsCount());
			members = add(members, s.getMembersCount());
			privateProjects = add(privateProjects, s.getPrivateProjectCount());
			languages = add(languages, s.getProgramLanguagesCount());
			publicProjects = add(publicProjects, s.getPublicProjectCount());
			tags = add(tags, s.getTagsCount());
			teams = add(teams, s.getTeamsCount());

			organizationList.add(s.getOrganizationName());


			if(snapshotDate==null) snapshotDate = s.getSnapshotDate();

			else if(snapshotDate.before(s.getSnapshotDate())) snapshotDate = s.getSnapshotDate();
		}

		String organizations = null;

		for(String org : organizationList){
			if (organizations == null)
			organizations = org;
		else
			organizations += delimeter + org;
		}

		//save aggregated values in new statistics object
		Statistics s = new Statistics(new Double(Math.random()*10000).intValue() , snapshotDate);
		s.setAllContributorsCount(contributers);
		s.setExternalContributorsCount(externalContributors);
		s.setAllForksCount(forks);
		s.setAllSizeCount(size);
		s.setAllStarsCount(stars);
		s.setMembersCount(members);
		s.setOrganizationName(organizations);
		s.setPrivateProjectCount(privateProjects);
		s.setProgramLanguagesCount(languages);
		s.setPublicProjectCount(publicProjects);
		s.setTagsCount(tags);
		s.setTeamsCount(teams);

		return s;
	}


	public  static Collection<Statistics> aggregateHistoricalStatistics(List<List<Statistics>> statisticsLists){

		if(statisticsLists.isEmpty()) return Collections.emptyList();

		if(statisticsLists.size()==1){
			return statisticsLists.iterator().next();
		}

		//TODO check if the lists have the same size

		//map statistics of the different organizations
		List<Statistics> aggregatedStatistics = new ArrayList<>();
		int numberOfRecords = statisticsLists.get(0).size(); //assuming that all organizations have the same amount of records

		List<Statistics> unaggregatedStatistics;

		for (int i=0; i<numberOfRecords; i++){
			unaggregatedStatistics  = new ArrayList<>();
			for (List<Statistics> orgStats : statisticsLists){

				if(orgStats.isEmpty()) continue;

				//FIXME figure out how to map the records
				//for now just use the order
				unaggregatedStatistics.add(orgStats.get(i));
			}

			Statistics aggregatedRecord = aggregateStatistics(unaggregatedStatistics);

			aggregatedStatistics.add(aggregatedRecord);
		}

		return aggregatedStatistics;
	}


	private static Integer add(Integer sum, Integer value){

		int tempSum = sum == null ? 0 : sum;

		if(value!=null) tempSum += value;

		return tempSum;
	}
}

public class ContributorStats {
    private String name;
    private List<String> organizationName;
    private String url;
    private List<Integer> organizationalCommitsCounts;
    private List<Integer> personalCommitsCounts;
    private List<Integer> organizationalProjectsCounts;
    private List<Integer> personalProjectsCounts;
    private List<Date> snapshotDates;

    public ContributorStats(List<Contributor> contributions) {
        Contributor first = contributions.get(0);
        name = first.getName();
        organizationName = new ArrayList<>();
        url = first.getUrl();
        contributions.sort((o1, o2) -> o1.getSnapshotDate().compareTo(o2.getSnapshotDate()));
        int size = contributions.size();
        organizationalCommitsCounts = new ArrayList<>(size);
        personalCommitsCounts = new ArrayList<>(size);
        organizationalProjectsCounts = new ArrayList<>(size);
        personalProjectsCounts = new ArrayList<>(size);
        snapshotDates = new ArrayList<>(size);
        int i = 0;
        Date lastSnapshotDate = null;
        String lastOrganizationName = null;
        for (Contributor c : contributions) {
            String loginId = c.getLoginId();
            if (loginId.isEmpty()) {
                throw new IllegalArgumentException("Contributor loginId could not be determinated.");
            }

            if (!loginId.equals(first.getLoginId())) {
                throw new IllegalArgumentException("All the contributors in the list must have the same loginId.");
            }

            if (lastSnapshotDate == null || !c.getSnapshotDate().equals(lastSnapshotDate)) {
                organizationalCommitsCounts.add(i, c.getOrganizationalCommitsCount());
                personalCommitsCounts.add(i, c.getPersonalCommitsCount());
                organizationalProjectsCounts.add(i, c.getOrganizationalProjectsCount());
                personalProjectsCounts.add(i, c.getPersonalProjectsCount());
                snapshotDates.add(i, c.getSnapshotDate());
                if (lastOrganizationName == null || !c.getOrganizationName().equals(lastOrganizationName)) {
                    organizationName.add(c.getOrganizationName());
                }
                i++;
            }
            // sum up the statistics if they are on the same day but for different organizations.
            // the prerequisite condition is to have all entries ordered by the name, date,
            if (lastSnapshotDate != null && c.getSnapshotDate().equals(lastSnapshotDate)) {
                if (!c.getOrganizationName().equals(lastOrganizationName)) {
                    organizationalCommitsCounts.set(
                        i-1, organizationalCommitsCounts.get(i-1)+c.getOrganizationalCommitsCount());
                    //personalCommitsCounts.set(
                    //    i-1, personalCommitsCounts.get(i-1)+c.getPersonalCommitsCount());
                    organizationalProjectsCounts.set(
                            i-1, organizationalProjectsCounts.get(i-1)+c.getOrganizationalProjectsCount());
                    personalProjectsCounts.set(
                            i-1, personalProjectsCounts.get(i-1)+c.getPersonalProjectsCount());
                }
            }
            lastSnapshotDate = c.getSnapshotDate();
            lastOrganizationName = c.getOrganizationName();
        }
    }

    @JsonProperty(value="name")
    public String getName() {return name;}

    @JsonProperty(value="organization_name")
    public List<String> getOrganizationName() {return organizationName;}

    @JsonProperty(value="url")
    public String getUrl() {return url;}

    @JsonProperty(value="organization_commit_counts")
    public List<Integer> getOrganizationalCommitsCounts() {return organizationalCommitsCounts;}

    @JsonProperty(value="personal_commit_counts")
    public List<Integer> getPersonalCommitsCounts() {return personalCommitsCounts;}

    @JsonProperty(value="organization_project_counts")
    public List<Integer> getOrganizationalProjectsCounts() {return organizationalProjectsCounts;}

    @JsonProperty(value="personal_project_counts")
    public List<Integer> getPersonalProjectsCounts() {return personalProjectsCounts;}

    @JsonProperty(value="snapshot_dates")
    @JsonSerialize(using = JsonDateListSerializer.class)
    public List<Date> getSnapshotDates() { return snapshotDates; }

    /**
     * Take a list of contributors and return a list their statistics that are seperated
     * by different contributors.
     *
     * @param contributors  a list consisting of contributors.
     * @return a list, each entry of which consists of statistics of the same contributors
     * at different date.
     */
    public static List<ContributorStats> buildStats(List<Contributor> contributors) {
        Map<String, List<Contributor>> contributorByLoginId = getDistinctContributors(contributors);
        return contributorByLoginId.values().stream()
                .map(ContributorStats::new)
                .collect(Collectors.toCollection(LinkedList::new));
    }

    /**
     * Take a list of contributors and return a map of lists where contributors have been partitioned
     * by loginId.
     *
     * @param contributors a list consisting of potentially different contributors.
     * @return a map which contains the list separated by contributors, using the loginId as index.
     */
    public static Map<String, List<Contributor>> getDistinctContributors(List<Contributor> contributors) {
        Map<String, List<Contributor>> result = new HashMap<>();
        for (Contributor contributor : contributors) {
            String loginId = contributor.getLoginId();
            if (loginId.isEmpty()) {
                throw new IllegalArgumentException("Could not determinate loginId.");
            }

            List<Contributor> list = result.get(loginId);
            if (list == null) {
                list = new LinkedList<>();
                result.put(loginId, list);
            }
            list.add(contributor);
        }
        return result;
    }

    @Override
    public String toString() {
        return String.format(
                "ContributorStats(%s, %s, %s, %s)", name, organizationName, url, snapshotDates);
    }
}

public class LanguageStats {

    private static final Logger logger = LoggerFactory.getLogger(LanguageStats.class);

    private String languageName;
    private List<Integer> projectCounts;
    private List<Date> snapshotDates;

    public static String UNKNOWN = "unknown";

    public LanguageStats(String languageName, List<Integer> projectCounts, List<Date> snapshotDates) {
        if (languageName == null) {
            this.languageName = UNKNOWN;
        } else {
            this.languageName = languageName;
        }
        this.projectCounts = projectCounts;
        this.snapshotDates = snapshotDates;
    }

    /**
     * Go through all the projects and collect the counts per snapshot and
     * per language.
     *
     * @param projectList
     * @return
     */
    public static List<LanguageStats> buildStats(List<Project> projectList) {
        List<Project> projects = filterUniqueSnapshots(projectList);

        // For each date, we have a map of all the counts. Later we piece the
        // results together from these pieces of information.
        Map<Date, Map<String,Integer>> counts = new HashMap<>();
        TreeSet<Date> dates = new TreeSet<>();
        Set<String> languages = new HashSet<>();

        for (Project p: projects) {
            String language = p.getPrimaryLanguage();
            Date date = p.getSnapshotDate();

            if (language == null)
                language = "unknown";

            dates.add(date);
            languages.add(language);

            Map<String,Integer> hist = counts.get(date);
            if (hist == null) {
                hist = new HashMap<>();
                counts.put(date, hist);
            }

            if (hist.containsKey(language)) {
                hist.put(language, hist.get(language) + 1);
            } else {
                hist.put(language, 1);
            }
        }

        List<LanguageStats> result = new ArrayList<>();
        for (String l: languages) {
            List<Integer> projectCounts = new ArrayList<>();
            List<Date> snapshotDates = new ArrayList<>(dates);

            for(Date d: snapshotDates) {
                Integer i = counts.get(d).get(l);
                if (i == null) {
                    projectCounts.add(0);
                } else {
                    projectCounts.add(i);
                }
            }
            result.add(new LanguageStats(l, projectCounts, snapshotDates));
        }
        return result;
    }

    /**
     * For some reason, there are duplicate snapshots sometimes. This method takes care of that
     * and removes the duplicates.
     *
     * @param projects
     * @return
     */
    public static List<Project> filterUniqueSnapshots(List<Project> projects) {
        Set<String> nameAndDateSet = new HashSet<>();

        int newCount = 0;
        int oldCount = 0;

        List<Project> result = new ArrayList<>();
        for (Project p: projects) {
            String key = p.getPrimaryLanguage() +
                    ":" + p.getName() +
                    ":" + p.getOrganizationName() +
                    ":" + p.getSnapshotDate().getTime();

            if (!nameAndDateSet.contains(key)) {
                newCount++;
                result.add(p);
                nameAndDateSet.add(key);
            } else {
                oldCount++;
            }
        }

        return result;
    }

    @JsonProperty(value="name")
    public String getLanguageName() {
        return languageName;
    }

    @JsonProperty(value="project_counts")
    public List<Integer> getProjectCounts() {
        return projectCounts;
    }

    @JsonProperty(value="snapshot_dates")
    @JsonSerialize(using = JsonDateListSerializer.class)
    public List<Date> getSnapshotDates() {
        return snapshotDates;
    }
}

public class ProjectStats {

    private String name;
    private String organizationName;
    private String url;
    private String description;
    private String primaryLanguage;
    private List<Integer> commitCounts;
    private List<Integer> forkCounts;
    private List<Integer> contributorsCounts;
    private List<Integer> scores;
    private List<Date> snapshotDates;

    public ProjectStats(List<Project> projects) {
        Project first = projects.get(0);

        name = first.getName();
        organizationName = first.getOrganizationName();
        url = first.getUrl();
        description = first.getDescription();
        primaryLanguage = first.getPrimaryLanguage();

        projects.sort((o1, o2) -> o1.getSnapshotDate().compareTo(o2.getSnapshotDate()));

        int size = projects.size();

        commitCounts = new ArrayList<>(size);
        forkCounts = new ArrayList<>(size);
        snapshotDates = new ArrayList<>(size);
        contributorsCounts = new ArrayList<>(size);
        scores = new ArrayList<>(size);

        int i = 0;

        Date lastSnapshotDate = null;

        for (Project p: projects) {
            if (!p.getName().equals(name)) {
                throw new IllegalArgumentException("All projects in the list must refer to the same project!");
            }

            if (lastSnapshotDate == null || !p.getSnapshotDate().equals(lastSnapshotDate)) {
                commitCounts.add(i, p.getCommitsCount());
                forkCounts.add(i, p.getForksCount());
                contributorsCounts.add(i, p.getContributorsCount());
                scores.add(i, p.getScore());
                snapshotDates.add(i, p.getSnapshotDate());
                i++;
            }

            lastSnapshotDate = p.getSnapshotDate();
        }
    }

    @JsonProperty(value="name")
    public String getName() { return name; }

    @JsonProperty(value="organization_name")
    public String getOrganizationName() { return organizationName; }

    @JsonProperty(value="url")
    public String getUrl() { return url; }

    @JsonProperty(value="primary_language")
    public String getPrimaryLanguage() { return primaryLanguage; }

    @JsonProperty(value="description")
    public String getDescription() { return description; }

    @JsonProperty(value="commit_counts")
    public List<Integer> getCommitCounts() { return commitCounts; }

    @JsonProperty(value="fork_counts")
    public List<Integer> getForkCounts() { return forkCounts; }

    @JsonProperty(value="contributors_counts")
    public List<Integer> getContributorsCounts() { return contributorsCounts; }

    @JsonProperty(value="scores")
    public List<Integer> getScores() { return scores; }

    @JsonProperty(value="snapshot_dates")
    @JsonSerialize(using = JsonDateListSerializer.class)
    public List<Date> getSnapshotDates() { return snapshotDates; }

    public static List<ProjectStats> buildStats(List<Project> projects) {
        Map<String,List<Project>> projectsByName = getDistinctProjects(projects);

        return projectsByName.values().stream()
                .map(ProjectStats::new)
                .collect(Collectors.toCollection(LinkedList::new));
    }

    /**
     * Take a list of projects and return a map of lists where projects have been partitioned
     * by names.
     *
     * @param projects list consisting of potentially different projects
     * @return a map which contains the list separated by project, using the name as index.
     */
    public static Map<String,List<Project>> getDistinctProjects(List<Project> projects)  {
        Map<String,List<Project>> result = new HashMap<>();

        for (Project project: projects) {
            String name = project.getName();

            List<Project> list = result.get(name);
            if (list == null) {
                list = new LinkedList<>();
                result.put(name, list);
            }

            list.add(project);
        }

        return result;
    }

    @Override
    public String toString() {
        return String.format("ProjectStats(%s, commitCounts=%s, forkCounts=%s, snapshotDates=%s)", name, commitCounts, forkCounts, snapshotDates);
    }
}

public class StringParser {

	/**
	 * Parses a list of strings given as String and separated with a delemiter,
	 * e.g. \"foo, bar, lock\"
	 * 
	 * @param stringList
	 * @param delimiter
	 * @return
	 */
	public static Collection<String> parseStringList(String stringList, String delimiter) {

		if (stringList == null)
			return Collections.emptyList();

		if (!stringList.contains(delimiter))
			return Lists.newArrayList(stringList);

		String[] array = stringList.split(delimiter);

		List<String> list = new ArrayList<>(array.length);

		for (String s : array) {
			list.add(s.trim());
		}

		return list;
	}

	public static String getISO8601StringForDate(Date date) {
		DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'", Locale.GERMANY);
		dateFormat.setTimeZone(TimeZone.getTimeZone("UTC"));
		return dateFormat.format(date);
	}

	public static Date parseIso8601Date(String iso8601Date) throws ParseException {
		return ISO8601Utils.parse(iso8601Date, new ParsePosition(0));
	}

}

