@Component
public class RetryableFetcher {

    private final Fetcher fetcher;
    private final int maxAttempts;
    private final int initialInterval;
    private final int maxInterval;
    private final double multiplier;
    private final MailSender mailSender;

    @Autowired
    public RetryableFetcher(Fetcher fetcher,
                            @Value("${fetcher.maxAttempts}") int maxAttempts,
                            @Value("${fetcher.initialInterval}") int initialInterval,
                            @Value("${fetcher.maxInterval}") int maxInterval,
                            @Value("${fetcher.multiplier}") double multiplier,
                            MailSender mailSender) {
        this.fetcher = fetcher;
        this.maxAttempts = maxAttempts;
        this.initialInterval = initialInterval;
        this.maxInterval = maxInterval;
        this.multiplier = multiplier;
        this.mailSender = mailSender;
    }

    public void tryFetchData() {
        RetryCallback<Boolean, RuntimeException> retryCallback = context -> fetcher.fetchData();
        RecoveryCallback<Boolean> recoveryCallback = retryContext -> mailSender.send(retryContext.getLastThrowable());
        retryTemplate().execute(retryCallback, recoveryCallback);
    }

    private RetryTemplate retryTemplate() {
        RetryTemplate template = new RetryTemplate();
        template.setBackOffPolicy(exponentialBackOffPolicy());
        template.setRetryPolicy(retryPolicy());
        return template;
    }

    private SimpleRetryPolicy retryPolicy() {
        return new SimpleRetryPolicy(maxAttempts, transientExceptions());
    }

    private ExponentialBackOffPolicy exponentialBackOffPolicy() {
        ExponentialBackOffPolicy exponentialBackOffPolicy = new ExponentialBackOffPolicy();

        exponentialBackOffPolicy.setInitialInterval(initialInterval);
        exponentialBackOffPolicy.setMaxInterval(maxInterval);
        exponentialBackOffPolicy.setMultiplier(multiplier);
        return exponentialBackOffPolicy;
    }

    private Map<Class<? extends Throwable>, Boolean> transientExceptions() {
        Map<Class<? extends Throwable>, Boolean> exceptions = new HashMap<>();
        exceptions.put(CrawlerRetryException.class, true);
        return exceptions;
    }


}

public class CrawlerRetryException extends RuntimeException {
    public CrawlerRetryException(Exception e) {
        super(e);
    }
}

@Component
public class Fetcher {

    private static final Logger logger = LoggerFactory.getLogger(Fetcher.class);

    private final ProjectRepository projectRepository;
    private final StatisticsRepository statisticsRepository;
    private final ContributorRepository contributorRepository;
    private final SnapshotProvider snapshotProvider;
    private final String[] organizations;

    @Autowired
    public Fetcher(ProjectRepository projectRepository,
                   StatisticsRepository statisticsRepository,
                   ContributorRepository contributorRepository,
                   SnapshotProvider snapshotProvider,
                   @Value("#{'${organization.list}'.split(',')}") String[] organizations) {
        this.projectRepository = projectRepository;
        this.statisticsRepository = statisticsRepository;
        this.contributorRepository = contributorRepository;
        this.snapshotProvider = snapshotProvider;
        this.organizations = organizations;
    }

    /**
     * This is used to fetch data from GitHub.
     */
    public boolean fetchData() {
        Date snapshotDate = from(now());

        logger.info("Starting fetching data. Snapshot date: {} {}, IP and MAC Address: {}.",
                snapshotDate, snapshotDate.getTime(), getIpAndMacAddress());

        List<Future<Snapshot>> futures = new ArrayList<>();

        try {
            for (String organizationName : organizations) {
                futures.add(snapshotProvider.takeSnapshot(organizationName, snapshotDate));
                logger.info("Enqueued task TakeSnapshotTask for organization '{}'.", organizationName);
            }
        } catch (IOException e) {
            logger.error("Unable to fetch data from GitHub API. Missing GitHub API credentials?.", e);
            throw new CrawlerRetryException(e);
        }
        logger.info("Submitted {} TakeSnapshotTasks.", futures.size());

        for (Future<Snapshot> future : futures) {
            try {
                Snapshot snapshot = future.get();

                statisticsRepository.save(snapshot.getStatistics());
                projectRepository.save(snapshot.getProjects());
                contributorRepository.save(snapshot.getContributors());
                // TODO languagesRepository.save(snapshot.getLanguages());

                logger.info("Successfully saved data for organization '{}'.", snapshot.getStatistics()
                        .getOrganizationName());
            } catch (InterruptedException | ExecutionException e) {
                logger.error("Error occurred while processing organization.", e);
                throw new CrawlerRetryException(e);
            }
        }
        logger.info("Finished fetching data.");
        return true;
    }

    private String getIpAndMacAddress() {
        try {
            InetAddress ip = InetAddress.getLocalHost();

            String mac = asList(getByInetAddress(ip).getHardwareAddress()).stream()
                    .map(b -> format("%02X", b))
                    .collect(joining("-"));

            return ip.getHostAddress() + "#" + mac;

        } catch (Exception e) {
            return "unknownAddress";
        }
    }
}

@Service
public class MailSender {

    private final JavaMailSender javaMailSender;
    private final String destinationAddress;
    private final String sourceAddress;

    @Autowired
    public MailSender(JavaMailSender javaMailSender,
                      @Value("${mail.to}") String destinationAddress,
                      @Value("${mail.from}") String sourceAddress) {
        this.javaMailSender = javaMailSender;
        this.destinationAddress = destinationAddress;
        this.sourceAddress = sourceAddress;
    }

    public boolean send(Throwable e) {
        javaMailSender.send(createMessageFor(e));
        return true;
    }

    private SimpleMailMessage createMessageFor(Throwable e) {
        SimpleMailMessage mailMessage = new SimpleMailMessage();
        mailMessage.setTo(destinationAddress);
        mailMessage.setFrom(sourceAddress);
        mailMessage.setSubject("GitHub crawler failed to fetch data");
        mailMessage.setText(format("%s\n%s", e.getMessage(), stream(e.getStackTrace()).map(StackTraceElement::toString).collect(joining("\n"))));
        return mailMessage;
    }

}

